export async function retry<T>(fn: () => Promise<T>, n = 3, b = 200, j = true, f?: (e: unknown) => boolean): Promise<T> {
  let last: unknown;
  for (let a = 0; a < n; a++) {
    try { return await fn(); } catch (e) {
      last = e;
      if (f && !f(e)) throw e;
      const wait = b * 2 ** a * (j ? 0.5 + Math.random() : 1);
      await new Promise(r => setTimeout(r, wait));
    }
  }
  throw last;
}

