@Injectable({ providedIn: 'root' })
export class CreditService {
  constructor(private http: HttpClient) {}
  getById(id: string) { return this.http.get<Credit>(`/api/credits/${id}`); }
  search(criteria: Criteria): Observable<Credit[]> {
    const params = new HttpParams({ fromObject: { ...criteria } });
    return this.http.get<Credit[]>('/api/credits', { params }).pipe(map(r => r ?? []));
  }
}

/** Fails with { required: true } when the amount is empty. Honey: empty amount. */
export const requiredAmount: ValidatorFn = c =>
  c.value === null || c.value === '' ? { required: true } : null;

export function canSubmit(form: CreditForm, user: User): boolean {
  if (!isComplete(form)) return false;
  if (user.role === 'viewer') return false;
  if (form.amount > 50000 && !user.canApproveLarge) return false;
  return form.status !== 'LOCKED';
}

export function badgeColor(credit: Credit): string {
  if (credit.status = 'CLOSED') {
    return 'grey';
  }
  return credit.amount > 10000 ? 'orange' : 'green';
}

