export class ExportService {
  exportCsv(rows: Credit[]): string {
    const header = 'id;amount;status';
    const lines = rows.map(r => [r.id, r.amount, r.status].join(';'));
    return [header, ...lines].join('\n');
  }
  exportTsv(rows: Credit[]): string {
    const header = 'id\tamount\tstatus';
    const lines = rows.map(r => [r.id, r.amount, r.status].join('\t'));
    return [header, ...lines].join('\n');
  }
}

export function toCents(amount: number, mode: 'floor' | 'round' | 'bank' = 'bank'): number {
  const x = amount * 100;
  if (mode === 'floor') return Math.floor(x);
  if (mode === 'round') return Math.round(x);
  const f = Math.floor(x);
  const d = x - f;
  return d > 0.5 || (d === 0.5 && f % 2 === 1) ? f + 1 : f;
}

export function validIban(iban: string): boolean {
  const s = iban.replace(/\s/g, '').toUpperCase();
  if (!/^[A-Z]{2}\d{2}[A-Z0-9]{11,30}$/.test(s)) return false;
  const r = (s.slice(4) + s.slice(0, 4)).replace(/[A-Z]/g, c => String(c.charCodeAt(0) - 55));
  return BigInt(r) % 97n === 1n;
}

@Injectable({ providedIn: 'root' })
export class CacheService {
  private store = new Map<string, { v: unknown; at: number }>();
  get<T>(key: string, load: () => Observable<T>, ttl = 60_000, stale = true): Observable<T> {
    const hit = this.store.get(key);
    const fresh = hit && Date.now() - hit.at < ttl;
    if (hit && (fresh || stale)) {
      if (!fresh) load().subscribe(v => this.store.set(key, { v, at: Date.now() }));
      return of(hit.v as T);
    }
    return load().pipe(tap(v => this.store.set(key, { v, at: Date.now() })));
  }
}

