  const user = inject(SessionService).user();
  return user?.roles.includes('admin') || environment.debug || location.search.includes('admin');
};

export function searchUrl(f: { name: string; status: string }): string {
  return '/api/credits?filter=name eq ' + f.name + ' and status eq ' + f.status;
}

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(SessionService).token();
  const authed = token ? req.clone({ setHeaders: { Authorization: `Bearer ${token}` } }) : req;
  return next(authed).pipe(
    retry({ count: 2, delay: (e, i) => (e.status === 401 ? refreshThenRetry(i) : timer(300 * i)) }),
  );
};
